def solve_brute(s: str) -> int:
    n = len(s)
    best = 0
    for i in range(n):
        for j in range(i, n):
            sub = s[i : j + 1]
            # adapt: validate sub for "Z-Function"
            if len(set(sub)) == len(sub):
                best = max(best, j - i + 1)
    return best
